parameters.functionScript:
let customerId = Inputs.CustomerId;
if(!customerId) {
    // No customer provided, create one before
    // creating the session
    const params = {}

    if(Inputs.CustomerEmail) params.email = Inputs.CustomerEmail;
    if(Inputs.CustomerName) params.name = Inputs.CustomerName;
    if(Inputs.Metadata) {
        Object.keys(Inputs.Metadata).forEach(k => {
            params['metadata[' + k + ']'] = Inputs.Metadata[k];
        })
    }

    const res = await fetch("https://api.stripe.com/v1/customers",{
        method:'POST',
        headers:{
            'authorization':'Bearer ' + Inputs.APIKey,
            'content-type':'application/x-www-form-urlencoded'
        },
        body:Object.keys(params).map(k => (k + '=' + encodeURIComponent(params[k]))).join('&')
    })

    if(res.ok) {
        const json = await res.json()

        customerId = json.id;
    }
    else {
        Outputs.Failure();
        throw Error("Failed to create customer for session")
    }
}
else {
    const params = {}
    // We have a customer, update the metadata
    if(Inputs.Metadata) {
        Object.keys(Inputs.Metadata).forEach(k => {
            params['metadata[' + k + ']'] = Inputs.Metadata[k];
        })
    }

    const res = await fetch("https://api.stripe.com/v1/customers/"+customerId,{
        method:'POST',
        headers:{
            'authorization':'Bearer ' + Inputs.APIKey,
            'content-type':'application/x-www-form-urlencoded'
        },
        body:Object.keys(params).map(k => (k + '=' + encodeURIComponent(params[k]))).join('&')
    })

    if(!res.ok) {
        Outputs.Failure();
        throw Error("Failed to update customer metadata") 
    }
}

// Create the session object
const params = {
        success_url:Inputs.SuccessUrl,
        cancel_url:Inputs.CancelUrl,
        mode:Inputs.Mode,
        customer:customerId
}

if(Inputs.LineItems) {
    Inputs.LineItems.forEach((i,idx) => {
        params['line_items[' + idx + '][price]'] = i.price;
        params['line_items[' + idx + '][quantity]'] = i.quantity; 
    })
}

const res = await fetch("https://api.stripe.com/v1/checkout/sessions",{
    method:'POST',
    headers:{
        'authorization':'Bearer ' + Inputs.APIKey,
        'content-type':'application/x-www-form-urlencoded'
    },
    body:Object.keys(params).map(k => (k + '=' + encodeURIComponent(params[k]))).join('&')
})

if(res.ok) {
    const json = await res.json()

    Outputs.SessionId = json.id;
    Outputs.CheckoutUrl = json.url;

    Outputs.Success();
}
else {
    Outputs.Failure();
    throw Error("Failed to create checkout session.")
}

const request = Noodl.Objects.Request;
const params = request.Parameters;

if(params.type === "checkout.session.completed" && params.data.object.mode === 'payment') {

    // Get the event from stripe, this also verifies that the
    // event is actually sent by stripe
    const eventRes = await fetch("https://api.stripe.com/v1/events/" + params.id,{
        headers:{
            "authorization":"Bearer " + Inputs.APIKey
        }
    })

    if(!eventRes.ok) {
        throw Error("Could not retrieve stripe event with id: " + params.id)
    }
    const eventJson = await eventRes.json();

    // Fetch the customer for the payment
    const customerRes = await fetch("https://api.stripe.com/v1/customers/" + eventJson.data.object.customer,{
        headers:{
            "authorization":"Bearer " + Inputs.APIKey
        }
    })

    if(!customerRes.ok) {
        throw Error("Could not retrieve customer for payment")
    }

    // Fetch the session again so we can get the line items
    const sessionRes = await fetch("https://api.stripe.com/v1/checkout/sessions/" + eventJson.data.object.id + "?expand[]=line_items",{
        headers:{
            "authorization":"Bearer " + Inputs.APIKey
        }
    })

    if(!sessionRes.ok) {
        throw Error("Could not retrieve session for payment")
    }

    const customer = await customerRes.json();
    const session = await sessionRes.json();
    Noodl.Object.create(session)
    Noodl.Object.create(customer)

    Outputs.CustomerId = eventJson.data.object.customer;

    try {
        Outputs.PaymentOwnerId = customer.metadata.payOwnerId;
        Outputs.Items = (session.line_items.data||[]).map(i => ({
            Quantity:i.quantity,
            PriceId:i.price.id,
            ProductId:i.price.product
        }))
    }
    catch(e) {}

    console.log(`Stripe ${params.type} event CustomerId:${eventJson.data.object.customer} OwnerId:${Outputs.PaymentOwnerId}`)


    Outputs.PaymentCompleted()
}

const request = Noodl.Objects.Request;
const params = request.Parameters;

if(params.type === "customer.subscription.created" || 
    params.type === "customer.subscription.updated" || 
    params.type === "customer.subscription.deleted") {

    // Get the event from stripe, this also verifies that the
    // event is actually sent by stripe
    const eventRes = await fetch("https://api.stripe.com/v1/events/" + params.id,{
        headers:{
            "authorization":"Bearer " + Inputs.APIKey
        }
    })

    if(!eventRes.ok) {
        throw Error("Could not retrieve stripe event with id: " + params.id)
    }
    const eventJson = await eventRes.json();

    // Fetch the customer for the subscription
    const customerRes = await fetch("https://api.stripe.com/v1/customers/" + eventJson.data.object.customer,{
        headers:{
            "authorization":"Bearer " + Inputs.APIKey
        }
    })

    if(!customerRes.ok) {
        throw Error("Could not retrieve customer for subscription")
    }

    const customer = await customerRes.json();
    const sub = eventJson.data.object;
    Noodl.Object.create(sub)
    Noodl.Object.create(customer)

    Outputs.CustomerId = sub.customer;
    Outputs.SubscriptionId = sub.id;
    Outputs.Status = sub.status;
    Outputs.CancelAtPeriodEnd = sub.cancel_at_period_end;

    try {
        Outputs.PriceId = sub.items.data[0].price.id;
        Outputs.ProductId = sub.items.data[0].price.product;
        Outputs.SubscriptionOwnerId = customer.metadata.subOwnerId;
    }
    catch(e) {}

    console.log(`Stripe ${params.type} event CustomerId:${sub.customer} SubscriptionId:${sub.id} OwnerId:${Outputs.SubscriptionOwnerId}`)

    if(params.type === "customer.subscription.created") Outputs.SubscriptionCreated()
    else if(params.type === "customer.subscription.updated") Outputs.SubscriptionUpdated()
    else if(params.type === "customer.subscription.deleted") Outputs.SubscriptionDeleted()
}

const res = await fetch("https://api.stripe.com/v1/invoices?customer=" + Inputs.CustomerId,{
    headers:{
        'authorization':'Bearer ' + Inputs.APIKey
    }
})

if(!res.ok) {
    Outputs.Failure();
    throw Error("Failed to fetch invoces")
}

const json = await res.json();

Outputs.Invoices = (json.data||[]).map(i => ({
    id:i.id,
    Status:i.status,
    ManageUrl:i.hosted_invoice_url,
    PdfUrl:i.invoice_pdf,
    PeriodStart:(new Date(i.period_start * 1000)).toISOString(),
    PeriodEnd:(new Date(i.period_end * 1000)).toISOString(),
    AmountDue:i.amount_due,
    AmountPaid:i.amount_paid,
    Currency:i.currency
}))

Outputs.Success();

Outputs.LineItems = (Inputs.Items||[]).map(i => ({
    price:i.PriceId,
    quantity:i.Quantity
}))

// This will be attached to the customer
// so we can retrieve it in the webhook
Outputs.Metadata = {
    payOwnerId:Inputs.OwnerId
}

Outputs.LineItems = [
    {price:Inputs.PriceId,
        quantity:Inputs.Quantity||1}
]

// This will be attached to the customer
// so we can retrieve it in the webhook
Outputs.Metadata = {
    subOwnerId:Inputs.OwnerId
}

if(Inputs.AtEndOfPeriod) {
    // Update the subscription to end at the end of period
    const params = {
        cancel_at_period_end:true
    }

    const res = await fetch("https://api.stripe.com/v1/subscriptions/" + Inputs.SubscriptionId,{
        method:'POST',
        headers:{
            'authorization':'Bearer ' + Inputs.APIKey,
            'content-type':'application/x-www-form-urlencoded'
        },
        body:Object.keys(params).map(k => (k + '=' + encodeURIComponent(params[k]))).join('&')
    })

    if(res.ok) {
        Outputs.Succes();
    }
    else Outputs.Failure();
}
else {
    // Delete the subscription right away
    const res = await fetch("https://api.stripe.com/v1/subscriptions/" + Inputs.SubscriptionId,{
        method:'DELETE',
        headers:{
            'authorization':'Bearer ' + Inputs.APIKey
        }
    })

    if(res.ok) {
        Outputs.Succes();
    }
    else Outputs.Failure();
}

const res = await fetch("https://api.stripe.com/v1/subscriptions?customer=" + Inputs.CustomerId,{
    headers:{
        'authorization':'Bearer ' + Inputs.APIKey
    }
})

if(res.ok) {
    const json = await res.json();

    if(json.data.length === 0) {
        Outputs.Failure()
    }
    else {
        const sub = json.data[0];
        Noodl.Object.create(sub);

        Outputs.Id = sub.id;
        Outputs.CancelAtPeriodEnd = sub.cancel_at_period_end;

        try {
            Outputs.ProductId = sub.items.data[0].price.product;
            Outputs.PriceId = sub.items.data[0].price.id;
            Outputs.Quantity = sub.items.data[0].price.quantity;
        }
        catch(e) {}

        Outputs.Success();
    }


}
else Outputs.Failure();

const params = {

}

if(Inputs.CancelAtPeriodEnd !== undefined) params.cancel_at_period_end = !!Inputs.CancelAtPeriodEnd;

if(Inputs.PriceId) {
    // First we must query the subscription to get the item id
    // we want to change
    const subRes = await fetch("https://api.stripe.com/v1/subscriptions/" + Inputs.SubscriptionId,{
        headers:{
            'authorization':'Bearer ' + Inputs.APIKey,
        }
    })

    if(!subRes.ok) { 
        Outputs.Failure(); 
        throw Error("Failed to get subscription for update") 
    }

    const sub = await subRes.json();

    if(!sub.items || !sub.items.data || sub.items.data.length !== 1) {
        Outputs.Failure();
        throw Error("Subscription must have only one item")
    }

    // update the subscription
    const itemId = sub.items.data[0].id;

    params['items[0][id]'] = itemId;
    params['items[0][price]'] = Inputs.PriceId;
    params['items[0][quantity]'] = Inputs.Quantity||1; 
}

const body = Object.keys(params).map(k => (k + '=' + encodeURIComponent(params[k]))).join('&')

const res = await fetch("https://api.stripe.com/v1/subscriptions/" + Inputs.SubscriptionId,{
    method:'POST',
    headers:{
        'authorization':'Bearer ' + Inputs.APIKey,
        'content-type':'application/x-www-form-urlencoded'
    },
    body
})

if(res.ok) {
    Outputs.Succes();
}
else Outputs.Failure()

